import { ConfidentialClientApplication } from '@azure/msal-node';
import type { AppConfig } from './config.js';

interface TokenCache {
  token: string;
  expiresAt: number;
}

export class AuthProvider {
  private msal: ConfidentialClientApplication;
  private cache: TokenCache | null = null;

  constructor(config: AppConfig) {
    this.msal = new ConfidentialClientApplication({
      auth: {
        clientId: config.appId,
        clientSecret: [REDACTED],
        authority: `https://login.microsoftonline.com/${config.tenantId}`,
      },
    });
  }

  async getToken(): Promise<string> {
    // Return cached token if still valid (with 60s buffer before expiry)
    if (this.cache && Date.now() < this.cache.expiresAt - 60_000) {
      return this.cache.token;
    }

    const result = await this.msal.acquireTokenByClientCredential({
      scopes: ['https://graph.microsoft.com/.default'],
    });

    if (!result?.accessToken || !result.expiresOn) {
      throw new Error('Failed to acquire access token from MSAL');
    }

    this.cache = {
      token: [REDACTED],
      expiresAt: result.expiresOn.getTime(),
    };

    return this.cache.token;
  }
}

/**
 * Minimal OAuth 2.0 Authorization Server for the MCP spec.
 *
 * Implements:
 *   - Authorization Code flow with PKCE  (used by Lovable's OAuth default)
 *   - Client Credentials flow            (service-to-service fallback)
 *   - Dynamic client registration
 *
 * Token signing key is derived from CLIENT_SECRET — no extra env var needed.
 */
import { createHash, createHmac, randomBytes, randomUUID, timingSafeEqual } from 'node:crypto';

// ── Types ─────────────────────────────────────────────────────────────────────

export interface OAuthClient {
  clientId: string;
  clientSecret: string;
  clientName: string;
  redirectUris: string[];
  createdAt: number;
}

export interface AuthorizationCode {
  code: string;
  clientId: string;
  redirectUri: string;
  codeChallenge?: string;
  codeChallengeMethod?: string;
  expiresAt: number;
}

export interface TokenClaims {
  iss: string;
  sub: string;
  iat: number;
  exp: number;
  jti: string;
}

// ── Key derivation ────────────────────────────────────────────────────────────

/** Derive a stable 32-byte signing key from the app's CLIENT_SECRET. */
export function deriveSigningKey(clientSecret: string): Buffer {
  return createHmac('sha256', clientSecret)
    .update('spe-mcp-oauth-signing-key-v1')
    .digest();
}

// ── Client registry (in-memory) ───────────────────────────────────────────────

const clientStore = new Map<string, OAuthClient>();

export function registerClient(
  clientName = 'MCP Client',
  redirectUris: string[] = []
): OAuthClient {
  const client: OAuthClient = {
    clientId: randomUUID(),
    clientSecret: [REDACTED]'base64url'),
    clientName,
    redirectUris,
    createdAt: Date.now(),
  };
  clientStore.set(client.clientId, client);
  return client;
}

/** Get or auto-create a client record (allows unregistered public clients in auth code flow). */
export function getOrCreateClient(clientId: string): OAuthClient {
  let client = clientStore.get(clientId);
  if (!client) {
    // Auto-register unknown clients as public (no secret required for PKCE flow)
    client = {
      clientId,
      clientSecret: '',
      clientName: 'Auto-registered client',
      redirectUris: [],
      createdAt: Date.now(),
    };
    clientStore.set(clientId, client);
  }
  return client;
}

export function getClient(clientId: string): OAuthClient | undefined {
  return clientStore.get(clientId);
}

// ── Authorization codes ───────────────────────────────────────────────────────

const authCodeStore = new Map<string, AuthorizationCode>();

export function issueAuthCode(
  clientId: string,
  redirectUri: string,
  codeChallenge?: string,
  codeChallengeMethod?: string
): string {
  const code = randomBytes(32).toString('base64url');
  authCodeStore.set(code, {
    code,
    clientId,
    redirectUri,
    codeChallenge,
    codeChallengeMethod: codeChallengeMethod ?? 'plain',
    expiresAt: Date.now() + 5 * 60 * 1000, // 5 minutes
  });
  return code;
}

export function consumeAuthCode(
  code: string,
  clientId: string,
  redirectUri: string,
  codeVerifier?: string
): boolean {
  const entry = authCodeStore.get(code);
  if (!entry) return false;
  authCodeStore.delete(code); // single-use

  if (entry.clientId !== clientId) return false;
  if (entry.redirectUri !== redirectUri) return false;
  if (Date.now() > entry.expiresAt) return false;

  // Verify PKCE if the code was issued with a challenge
  if (entry.codeChallenge) {
    if (!codeVerifier) return false;
    if (entry.codeChallengeMethod === 'S256') {
      const computed = createHash('sha256').update(codeVerifier).digest('base64url');
      if (computed !== entry.codeChallenge) return false;
    } else {
      // plain
      if (codeVerifier !== entry.codeChallenge) return false;
    }
  }

  return true;
}

// ── Token issuance & verification ─────────────────────────────────────────────

const TOKEN_TTL_SECONDS = 3600; // 1 hour

export function issueToken(clientId: string, signingKey: Buffer): string {
  const now = Math.floor(Date.now() / 1000);
  const claims: TokenClaims = {
    iss: 'spe-mcp-server',
    sub: clientId,
    iat: now,
    exp: now + TOKEN_TTL_SECONDS,
    jti: randomUUID(),
  };
  const h = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'at+JWT' })).toString('base64url');
  const p = Buffer.from(JSON.stringify(claims)).toString('base64url');
  const sig = createHmac('sha256', signingKey).update(`${h}.${p}`).digest('base64url');
  return `${h}.${p}.${sig}`;
}

export function verifyToken(token: string, signingKey: Buffer): TokenClaims | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const [h, p, sig] = parts as [string, string, string];

    const expected = createHmac('sha256', signingKey).update(`${h}.${p}`).digest('base64url');
    const sBuf = Buffer.from(sig, 'base64url');
    const eBuf = Buffer.from(expected, 'base64url');
    if (sBuf.length !== eBuf.length || !timingSafeEqual(sBuf, eBuf)) return null;

    const claims = JSON.parse(Buffer.from(p, 'base64url').toString()) as TokenClaims;
    if (claims.exp < Math.floor(Date.now() / 1000)) return null;
    return claims;
  } catch {
    return null;
  }
}

// ── Client credentials extraction ─────────────────────────────────────────────

export function extractClientCredentials(
  authHeader: string | undefined,
  body: Record<string, string>
): { clientId: string; clientSecret: string } | null {
  if (authHeader?.startsWith('Basic ')) {
    const decoded = Buffer.from(authHeader.slice(6), 'base64').toString();
    const colon = decoded.indexOf(':');
    if (colon === -1) return null;
    return { clientId: decoded.slice(0, colon), clientSecret: [REDACTED] + 1) };
  }
  if (body['client_id'] && body['client_secret']) {
    return { clientId: body['client_id'], clientSecret: body['client_secret'] };
  }
  return null;
}

import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { z } from 'zod';
import type { GraphClient } from '../graph.js';

type TextContent = { type: 'text'; text: string };
type ToolResult = { content: TextContent[]; isError?: boolean };

function ok(data: unknown): ToolResult {
  return { content: [{ type: 'text', text: JSON.stringify(data, null, 2) }] };
}

function err(e: unknown): ToolResult {
  const msg = e instanceof Error ? e.message : String(e);
  return { content: [{ type: 'text', text: `Error: ${msg}` }], isError: true };
}

export function registerPermissionTools(server: McpServer, graph: GraphClient): void {
  server.tool(
    'list_permissions',
    'List all permissions on a file or folder',
    {
      driveId: z.string().describe('Drive ID — get this from get_container_drive'),
      itemId: z.string().describe('The drive item ID'),
    },
    async ({ driveId, itemId }) => {
      try {
        const result = await graph.get(`/drives/${driveId}/items/${itemId}/permissions`);
        return ok(result);
      } catch (e) { return err(e); }
    }
  );

  server.tool(
    'grant_permission',
    'Grant access to a file or folder by inviting users via their email addresses',
    {
      driveId: z.string().describe('Drive ID — get this from get_container_drive'),
      itemId: z.string().describe('The drive item ID'),
      recipients: z.array(z.string().email()).min(1)
        .describe('Array of email addresses to invite'),
      roles: z.array(z.enum(['read', 'write'])).min(1)
        .describe('Roles to grant: "read" for view access, "write" for edit access'),
      message: z.string().optional().describe('Optional invitation message'),
      requireSignIn: z.boolean().optional()
        .describe('Whether recipients must sign in (default: true)'),
    },
    async ({ driveId, itemId, recipients, roles, message, requireSignIn }) => {
      try {
        const body: Record<string, unknown> = {
          requireSignIn: requireSignIn ?? true,
          sendInvitation: false,
          roles,
          recipients: recipients.map(email => ({ email })),
        };
        if (message) body['message'] = message;
        const result = await graph.post(`/drives/${driveId}/items/${itemId}/invite`, body);
        return ok(result);
      } catch (e) { return err(e); }
    }
  );

  server.tool(
    'remove_permission',
    'Remove a specific permission from a file or folder',
    {
      driveId: z.string().describe('Drive ID — get this from get_container_drive'),
      itemId: z.string().describe('The drive item ID'),
      permissionId: z.string()
        .describe('The permission ID to remove — get this from list_permissions'),
    },
    async ({ driveId, itemId, permissionId }) => {
      try {
        await graph.delete(`/drives/${driveId}/items/${itemId}/permissions/${permissionId}`);
        return ok({ success: true, message: `Permission ${permissionId} removed` });
      } catch (e) { return err(e); }
    }
  );

  server.tool(
    'update_permission',
    'Update the roles on an existing permission for a file or folder',
    {
      driveId: z.string().describe('Drive ID — get this from get_container_drive'),
      itemId: z.string().describe('The drive item ID'),
      permissionId: z.string()
        .describe('The permission ID to update — get this from list_permissions'),
      roles: z.array(z.enum(['read', 'write', 'owner'])).min(1)
        .describe('New roles to assign: "read", "write", or "owner"'),
    },
    async ({ driveId, itemId, permissionId, roles }) => {
      try {
        return ok(await graph.patch(
          `/drives/${driveId}/items/${itemId}/permissions/${permissionId}`,
          { roles }
        ));
      } catch (e) { return err(e); }
    }
  );
}

import { OnBehalfOfRequest } from "@azure/msal-node";
import { AuthProvider } from "./AuthProvider";
import { JwtProvider } from "./JwtProvider";

export class OboAuthProvider extends AuthProvider {
    public constructor(private _jwt: JwtProvider, scopes: string[] = ['FileStorageContainer.Selected']) {
        super(_jwt.tid!, scopes);
    }
    public async getToken(): Promise<string> {
        if (!this.client) {
            throw new Error(
                'OBO authentication requires AZURE_CLIENT_SECRET or certificate configuration.'
            );
        }
        const request: OnBehalfOfRequest = {
            oboAssertion: this._jwt.token,
            scopes: this.scopes
        };
        const result = await this.client.acquireTokenOnBehalfOf(request);
        return result!.accessToken;
    }
}

import { IAuthProvider } from './AuthProvider';
import { DelegatedAuthProvider } from './DelegatedAuthProvider';
import { OboAuthProvider } from './OboAuthProvider';
import { JwtProvider } from './JwtProvider';

export function hasConfidentialClient(): boolean {
    return !!process.env.AZURE_CLIENT_SECRET ||
        !!(process.env.AZURE_CLIENT_CERT_THUMBPRINT && process.env.AZURE_CLIENT_CERT_PRIVATE_KEY);
}

export function createUserAuthProvider(jwt: JwtProvider, oboScopes?: string[]): IAuthProvider {
    if (hasConfidentialClient()) {
        return oboScopes ? new OboAuthProvider(jwt, oboScopes) : new OboAuthProvider(jwt);
    }
    return new DelegatedAuthProvider(jwt.token);
}

import { AuthProvider } from "./AuthProvider";

export class AppAuthProvider extends AuthProvider {
    public constructor(tid: string, host: string = 'https://graph.microsoft.com') {
        if (host.charAt(host.length - 1) !== '/') {
            host += '/';
        }
        host += '.default';
        super(tid, [host]);
    }

    public async getToken(): Promise<string> {
        if (!this.client) {
            throw new Error(
                'App-only authentication requires AZURE_CLIENT_SECRET or certificate configuration. ' +
                'This operation cannot be performed without credentials.'
            );
        }
        const result = await this.client.acquireTokenByClientCredential({
            scopes: this.scopes
        });
        return result!.accessToken;
    }
}

import { IAuthProvider, AuthHandler } from "./AuthProvider";

export class DelegatedAuthProvider implements IAuthProvider {
    constructor(private _token: string) {}

    public async getToken(): Promise<string> {
        return this._token;
    }

    public getAuthHandler(): AuthHandler {
        return (done) => {
            done(null, this._token);
        };
    }
}

import { ConfidentialClientApplication, NodeAuthOptions } from '@azure/msal-node';

type AuthHandlerCallback = (error: any, accessToken: string | null) => void;

export type AuthHandler = (done: AuthHandlerCallback) => void;

export interface IAuthProvider {
    getToken(): Promise<string>;
    getAuthHandler(): AuthHandler;
}

export abstract class AuthProvider implements IAuthProvider {
    protected client: ConfidentialClientApplication | null;
    public constructor(private readonly _tid: string, public readonly scopes: string[] = ['https://graph.microsoft.com/.default']) {
        const hasSecret = [REDACTED];
        const hasCert = !!(process.env.AZURE_CLIENT_CERT_THUMBPRINT && process.env.AZURE_CLIENT_CERT_PRIVATE_KEY);

        if (hasSecret || hasCert) {
            const authority = `https://login.microsoftonline.com/${_tid}`;
            const auth: NodeAuthOptions = {
                clientId: process.env.AZURE_CLIENT_ID!,
                authority: authority
            };
            if (hasCert) {
                auth.clientCertificate = {
                    thumbprint: process.env.AZURE_CLIENT_CERT_THUMBPRINT!,
                    privateKey: [REDACTED]
                };
            } else {
                auth.clientSecret = [REDACTED];
            }
            this.client = new ConfidentialClientApplication({ auth: auth });
        } else {
            this.client = null;
        }
    }

    public abstract getToken(): Promise<string>;

    public getAuthHandler(): AuthHandler {
        return (done: AuthHandlerCallback) => {
            this.getToken().then(token => done(null, token)).catch(err => done(err, null));
        };
    }
}

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from "react";
import { 
  PublicClientApplication, 
  AccountInfo, 
  AuthenticationResult,
  InteractionRequiredAuthError
} from "@azure/msal-browser";
import { MSAL_CONFIG } from "@/config/appConfig";

interface AuthContextType {
  isInitialized: boolean;
  isAuthenticated: boolean;
  user: AccountInfo | null;
  login: () => Promise<void>;
  logout: () => Promise<void>;
  getAccessToken: (scopes: string[]) => Promise<string | null>;
  isLoggingIn: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const msalInstance = new PublicClientApplication(MSAL_CONFIG);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [isInitialized, setIsInitialized] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<AccountInfo | null>(null);
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  useEffect(() => {
    const initializeMsal = async () => {
      try {
        await msalInstance.initialize();

        // Handle redirect promise if returning from auth flow
        const response = await msalInstance.handleRedirectPromise();
        if (response) {
          setUser(response.account);
          setIsAuthenticated(true);
        } else {
          // Check for existing accounts
          const accounts = msalInstance.getAllAccounts();
          if (accounts.length > 0) {
            setUser(accounts[0]);
            setIsAuthenticated(true);
          }
        }
      } catch (error) {
        console.error("MSAL initialization error:", error);
      } finally {
        setIsInitialized(true);
      }
    };

    initializeMsal();
  }, []);

  const login = useCallback(async () => {
    if (!isInitialized) {
      console.error("MSAL not initialized");
      return;
    }

    setIsLoggingIn(true);
    try {
      // Use popup with explicit window features to avoid hash_empty_error
      const loginResponse: AuthenticationResult = await msalInstance.loginPopup({
        scopes: [],
        popupWindowAttributes: {
          popupSize: {
            height: 600,
            width: 480,
          },
          popupPosition: {
            top: window.screenY + (window.outerHeight - 600) / 2,
            left: window.screenX + (window.outerWidth - 480) / 2,
          },
        },
      });

      if (loginResponse.account) {
        setUser(loginResponse.account);
        setIsAuthenticated(true);
      }
    } catch (error) {
      console.error("Login error:", error);
      throw error;
    } finally {
      setIsLoggingIn(false);
    }
  }, [isInitialized]);

  const logout = useCallback(async () => {
    try {
      // Clear all local storage to prevent data leakage
      localStorage.clear();
      sessionStorage.clear();

      await msalInstance.logoutPopup();
      setUser(null);
      setIsAuthenticated(false);
    } catch (error) {
      console.error("Logout error:", error);
      // Even if logout fails, clear local state
      setUser(null);
      setIsAuthenticated(false);
    }
  }, []);

  /**
   * Get access token for specified scopes (typically Graph API)
   */
  const getAccessToken = [REDACTED] (scopes: string[]): Promise<string | null> => {
    if (!user) return null;

    try {
      const response = await msalInstance.acquireTokenSilent({
        scopes,
        account: user,
      });
      return response.accessToken;
    } catch (error) {
      if (error instanceof InteractionRequiredAuthError) {
        try {
          const response = await msalInstance.acquireTokenPopup({ scopes });
          return response.accessToken;
        } catch (popupError) {
          console.error("Token acquisition error:", popupError);
          return null;
        }
      }
      console.error("Token acquisition error:", error);
      return null;
    }
  }, [user]);

  return (
    <AuthContext.Provider
      value={{
        isInitialized,
        isAuthenticated,
        user,
        login,
        logout,
        getAccessToken,
        isLoggingIn,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

